" required></div><div class="col-md-2"><input name="items[${n}][quantity]" type="number" step=".01" min=".01" class="form-control" placeholder="Qty" required></div><div class="col-md-3"><input name="items[${n}][unit_price]" type="number" step=".01" min="0" class="form-control" placeholder="Unit price" required></div><div class="col-md-1"><button type="button" class="btn btn-outline-danger remove">×</button></div></div>`);n++};document.addEventListener('click',e=>{if(e.target.classList.contains('remove'))e.target.closest('.item').remove()});</script>@endsection
